"""Sections 18-21, 36: is the whole window generated by ONE screw?

CODEX_IMPLEMENT_DUAL_DIFFERENTIAL_FINITE_JOINT_DISCOVERY.md.

A one-degree-of-freedom joint does not merely move the part; it moves it along
a single fixed screw, so every frame's twist is the SAME six-vector scaled by
that frame's rate:

    xi_t = qdot_t xi_J.

Stacking the frames, X = [xi_1 ... xi_T] is then rank 1 -- and the angular
block W = [omega_1 ... omega_T] is rank 0 for prismatic and rank 1 for
revolute. That is the structure this module measures.

Sections 18 and 24 both forbid deciding it with a hardcoded singular-value
ratio, and section 6 forbids a threshold on ||omega||. So the rank question is
asked as a weighted goodness of fit against the per-frame information: is the
rank-0 model (nothing there) consistent with the data, and is the rank-1 model
(one axis) consistent with it? Two chi-squares with honest degrees of freedom,
not a ratio with a magic number.

Section 36 is the standing caveat: even prismatic data produces a small noisy
angular block, so this fit is a parameter estimator, an initializer and a
physical consistency test -- never the final classifier on its own.
"""

from __future__ import annotations

import math

import torch

from .joint_information import information_inverse


def _metric(d: int, length_scale: float | None, device) -> torch.Tensor:
    """Scaling that makes a 6-vector twist's two halves comparable.

    [v; omega] mixes length/time with 1/time, so "unit norm" is meaningless
    until the translation half is divided by a length. The part's own radius
    is the only length in the problem that is not arbitrary.
    """
    s = torch.ones(d, dtype=torch.float64, device=device)
    if d == 6 and length_scale:
        s[:3] = 1.0 / max(float(length_scale), 1e-300)
    return torch.diag(s)


def weighted_rank_one(columns, information=None, *, length_scale=None,
                      iters: int = 64, tol: float = 1e-14) -> dict:
    """Covariance-aware rank-1 factorisation columns_t ~ rate_t * direction.

    Alternating weighted least squares: with the direction fixed each rate is
    a scalar projection in the information metric, and with the rates fixed
    the direction is one weighted normal-equation solve. Both steps are exact,
    so this converges monotonically and needs no step size.

    The two chi-squares returned are what sections 18, 19 and 24 actually
    want. `chi2_rank0` tests "there is nothing here" (all columns zero);
    `chi2_rank1` tests "there is one common direction". Each comes with its
    degrees of freedom, so a caller compares a statistic with its expectation
    instead of a singular-value ratio with a constant.
    """
    X = torch.as_tensor(columns).double()
    if X.ndim != 2:
        raise ValueError("columns must be [T, d]")
    T, d = X.shape
    dev = X.device
    if information is None:
        F = torch.eye(d, dtype=torch.float64, device=dev).expand(T, d, d)
    else:
        F = torch.as_tensor(information).double()
        if F.ndim == 1:
            F = F[:, None, None] * torch.eye(d, dtype=torch.float64, device=dev)

    S = _metric(d, length_scale, dev)
    Sinv = torch.linalg.inv(S)

    # rank 0: the null model, every column exactly zero
    chi2_0 = float(torch.einsum("ti,tij,tj->", X, F, X))

    if T == 0:
        return {"direction": torch.zeros(d, dtype=torch.float64, device=dev),
                "rates": torch.zeros(0, dtype=torch.float64, device=dev),
                "chi2_rank0": 0.0, "dof_rank0": 0,
                "chi2_rank1": 0.0, "dof_rank1": 0,
                "residual": X, "converged": True, "iterations": 0}

    # start from the unweighted leading right-singular vector in the metric
    try:
        v0 = torch.linalg.svd(X @ Sinv, full_matrices=False).Vh[0]
        direction = S @ v0
    except Exception:
        direction = torch.zeros(d, dtype=torch.float64, device=dev)
        direction[0] = 1.0
    nrm = (Sinv @ direction).norm().clamp_min(1e-300)
    direction = direction / nrm

    rates = torch.zeros(T, dtype=torch.float64, device=dev)
    prev = float("inf")
    it = 0
    for it in range(1, int(iters) + 1):
        den = torch.einsum("i,tij,j->t", direction, F, direction)
        rates = torch.where(den > 0,
                            torch.einsum("i,tij,tj->t", direction, F, X)
                            / den.clamp_min(1e-300),
                            torch.zeros_like(den))
        A = torch.einsum("t,tij->ij", rates * rates, F)
        b = torch.einsum("t,tij,tj->i", rates, F, X)
        nxt = information_inverse(A)["inverse"] @ b
        n2 = (Sinv @ nxt).norm()
        if not torch.isfinite(n2) or float(n2) <= 0.0:
            break
        direction = nxt / n2.clamp_min(1e-300)
        resid = X - rates[:, None] * direction[None, :]
        chi2 = float(torch.einsum("ti,tij,tj->", resid, F, resid))
        if abs(prev - chi2) <= tol * max(1.0, abs(chi2)):
            prev = chi2
            break
        prev = chi2

    # Gauge: xi_t = qdot_t xi_J is unchanged by flipping BOTH the direction
    # and every rate, so the factorisation has a free sign. Left alone it is
    # decided by whichever way the SVD happened to point, which makes the
    # reported axis direction and the sign of q non-reproducible between runs
    # on the same data. Fixing it so the motion advances (rates summing
    # positive, with the largest-magnitude rate breaking a tie) costs nothing
    # and makes q(t) increase along the joint as the rest of the pipeline
    # assumes.
    total = float(rates.sum())
    if total < 0.0 or (total == 0.0 and rates.numel()
                       and float(rates[int(rates.abs().argmax())]) < 0.0):
        direction = -direction
        rates = -rates

    resid = X - rates[:, None] * direction[None, :]
    chi2_1 = float(torch.einsum("ti,tij,tj->", resid, F, resid))
    # rank-1 model spends T rates and (d - 1) direction parameters
    dof1 = max(T * d - T - (d - 1), 0)
    return {"direction": direction, "rates": rates,
            "chi2_rank0": chi2_0, "dof_rank0": T * d,
            "chi2_rank1": chi2_1, "dof_rank1": dof1,
            "rank0_per_dof": chi2_0 / max(T * d, 1),
            "rank1_per_dof": chi2_1 / max(dof1, 1),
            "residual": resid, "iterations": it,
            "converged": bool(it < int(iters)),
            "metric_length_scale": length_scale}


# ---------------------------------------------------------------------------
# sections 18, 19: angular and full-twist structure
# ---------------------------------------------------------------------------
def angular_rank_evidence(omega, information=None) -> dict:
    """Section 18: W = [omega_1 ... omega_T] is rank 0 for P, rank 1 for R."""
    r = weighted_rank_one(omega, information)
    return {**r,
            "axis": r["direction"],
            "qdot": r["rates"],
            "interpretation": ("section 18: rank 0 (chi2_rank0 consistent "
                               "with its dof) means no angular motion; rank 1 "
                               "means one fixed axis")}


def twist_rank_evidence(xi, information=None, *, length_scale=None) -> dict:
    """Section 19: X = [xi_1 ... xi_T] must be rank 1 for any one-DoF joint."""
    r = weighted_rank_one(xi, information, length_scale=length_scale)
    return {**r, "xi_J": r["direction"], "qdot": r["rates"],
            "interpretation": ("section 19: a one-DoF joint has "
                               "xi_t = qdot_t xi_J, so a large rank-1 residual "
                               "means the motion is not one joint at all")}


# ---------------------------------------------------------------------------
# sections 20, 21: reading the geometry out of the common screw
# ---------------------------------------------------------------------------
def fit_prismatic_generator(xi, information=None, *,
                            length_scale=None) -> dict:
    """Section 20: xi_J^P = [d; 0], the angular block constrained to zero.

    Fitted on the translation block alone, which IS the constraint -- not a
    penalty on omega that could be traded away.
    """
    X = torch.as_tensor(xi).double()
    F = None
    if information is not None:
        F = torch.as_tensor(information).double()[:, :3, :3]
    r = weighted_rank_one(X[:, :3], F)
    d = r["direction"]
    xi_J = torch.cat([d, torch.zeros(3, dtype=torch.float64, device=d.device)])
    return {**r, "direction_of_travel": d, "xi_J": xi_J,
            "kind": "prismatic",
            "note": "section 20: omega is held at exactly zero, not penalised"}


def fit_revolute_generator(xi, information=None, *,
                           length_scale=None) -> dict:
    """Section 21: xi_J^R = [-e x a; e] -- axis direction and a point on it.

    For a twist [v; omega] the screw axis has direction e = omega/||omega||,
    its closest point to the world origin is a = (omega x v)/||omega||^2, and
    the pitch is (omega . v)/||omega||^2. A revolute joint has zero pitch, so
    the recovered pitch is reported as a physical consistency check rather
    than assumed away: a large pitch means the motion is a screw, not a hinge.
    """
    r = twist_rank_evidence(xi, information, length_scale=length_scale)
    xi_J = r["xi_J"]
    v, om = xi_J[:3], xi_J[3:]
    n = om.norm()
    if float(n) <= 0.0:
        return {**r, "kind": "revolute", "axis_direction": None,
                "axis_point": None, "pitch": None,
                "identifiable": False,
                "note": ("section 21: the angular block vanished, so no "
                         "revolute axis exists in this chart")}
    e = om / n
    a = torch.linalg.cross(om, v) / (n * n)
    pitch = float((om @ v) / (n * n))
    return {**r, "kind": "revolute", "axis_direction": e, "axis_point": a,
            "pitch": pitch, "identifiable": True,
            "zero_pitch_residual": abs(pitch),
            "note": ("section 21: e = omega/||omega||, a = (omega x v)/"
                     "||omega||^2, pitch = (omega.v)/||omega||^2; a hinge has "
                     "zero pitch")}


def fit_weighted_common_screw(xi, information=None, *, length_scale=None,
                              omega=None, omega_information=None) -> dict:
    """Sections 18-21 together: both generators, and the evidence for each.

    Returns the prismatic and revolute fits side by side with the angular rank
    evidence, and no verdict. Section 36 is explicit that the common screw is
    "parameter estimator, initialization, physical consistency test" and "not
    the final P/R statistical test by itself", so choosing between them is
    left to `differential_finite_consistency` and the RGB-D branch.
    """
    X = torch.as_tensor(xi).double()
    full = twist_rank_evidence(X, information, length_scale=length_scale)
    pris = fit_prismatic_generator(X, information, length_scale=length_scale)
    rev = fit_revolute_generator(X, information, length_scale=length_scale)
    ang = angular_rank_evidence(X[:, 3:] if omega is None else omega,
                                omega_information)
    return {"twist_rank": full, "angular_rank": ang,
            "prismatic": pris, "revolute": rev,
            "xi_J": full["xi_J"],
            "rank1_residual": full["chi2_rank1"],
            "note": ("section 36: a parameter estimator and consistency "
                     "test, never the classifier on its own")}


# ---------------------------------------------------------------------------
# the joint coordinate
# ---------------------------------------------------------------------------
def estimate_qdot(xi, xi_J, information=None) -> torch.Tensor:
    """The rate along a KNOWN screw: qdot_t = (xi_J^T F_t xi_t)/(xi_J^T F_t xi_J)."""
    X = torch.as_tensor(xi).double()
    g = torch.as_tensor(xi_J).double().reshape(-1)
    T, d = X.shape
    if information is None:
        F = torch.eye(d, dtype=torch.float64, device=X.device).expand(T, d, d)
    else:
        F = torch.as_tensor(information).double()
    den = torch.einsum("i,tij,j->t", g, F, g)
    return torch.where(den > 0,
                       torch.einsum("i,tij,tj->t", g, F, X)
                       / den.clamp_min(1e-300), torch.zeros_like(den))


def integrate_q(qdot, times=None, dt: float = 1.0, q0: float = 0.0) -> torch.Tensor:
    """q(t) by trapezoidal integration of qdot, gauged to q(t_0) = q0.

    Trapezoid rather than a rectangle sum because qdot already comes from a
    second-order difference; a first-order integration would throw that away
    and bias the total sweep.
    """
    r = torch.as_tensor(qdot).double().reshape(-1)
    T = int(r.numel())
    t = (torch.arange(T, dtype=torch.float64, device=r.device) * float(dt)
         if times is None else torch.as_tensor(times).double().reshape(-1))
    if T == 0:
        return r
    h = t[1:] - t[:-1]
    inc = 0.5 * (r[1:] + r[:-1]) * h
    return torch.cat([torch.full((1,), float(q0), dtype=torch.float64,
                                 device=r.device),
                      torch.cumsum(inc, 0) + float(q0)])


def chi2_quantile(dof: int, confidence: float = 0.95) -> float:
    """The (1 - alpha) point of a chi-square with `dof` degrees of freedom.

    Sections 6, 18 and 25 all forbid magnitude thresholds, and this is what
    replaces them. A chi-square statistic is compared with the quantile of its
    OWN null distribution, so the cut is a property of the hypothesis and the
    degrees of freedom, not a number chosen per scene. One confidence is set
    for the whole run and applies to every part of every dataset.

    SciPy gives the exact value; the Wilson-Hilferty cube-root approximation
    is the fallback, which is within a fraction of a percent for dof >= 1 and
    keeps the module importable without SciPy.
    """
    k = max(int(dof), 1)
    a = min(max(float(confidence), 1e-6), 1 - 1e-12)
    try:
        from scipy.stats import chi2 as _chi2
        return float(_chi2.ppf(a, k))
    except Exception:
        z = float(math.sqrt(2.0) * torch.erfinv(
            torch.tensor(2.0 * a - 1.0, dtype=torch.float64)))
        t = 1.0 - 2.0 / (9.0 * k) + z * math.sqrt(2.0 / (9.0 * k))
        return float(k * max(t, 0.0) ** 3)
